function validate([n, maxDistance, roads]) {
  if (!Number.isInteger(n) || n < 1 || n > 10) return 'n is between 1 and 10.';
  if (!Number.isInteger(maxDistance) || maxDistance < 1 || maxDistance > 100000) return 'maxDistance is between 1 and 10^5.';
  if (!Array.isArray(roads) || roads.length > 1000) return 'There are at most 1000 roads.';
  for (const road of roads) {
    if (!Array.isArray(road) || road.length !== 3) return 'Each road is [u, v, w].';
    const [u, v, w] = road;
    if (![u, v].every(x => Number.isInteger(x) && x >= 0 && x < n)) return 'Road ends are branches 0 to n - 1.';
    if (u === v) return 'A road joins two different branches.';
    if (!Number.isInteger(w) || w < 1 || w > 1000) return 'Road lengths are between 1 and 1000.';
  }
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  let parts = n;
  for (const [u, v] of roads) {
    const a = find(u), b = find(v);
    if (a !== b) { parent[a] = b; parts--; }
  }
  if (parts !== 1) return 'At the start every branch must be reachable from every other one.';
  return null;
}

