function numberOfSets(n, maxDistance, roads) {
  let answer = 0;
  for (let mask = 0; mask < 2 ** n; mask++) {
    const open = [];
    for (let b = 0; b < n; b++) if (mask & (1 << b)) open.push(b);
    let ok = true;
    for (const source of open) {
      const best = new Array(n).fill(Infinity);
      best[source] = 0;
      for (let round = 0; round < n; round++) {
        for (const [u, v, w] of roads) {
          if (!open.includes(u) || !open.includes(v)) continue;
          if (best[u] + w < best[v]) best[v] = best[u] + w;
          if (best[v] + w < best[u]) best[u] = best[v] + w;
        }
      }
      if (open.some(t => best[t] > maxDistance)) ok = false;
    }
    if (ok) answer++;
  }
  return answer;
}

