function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(8, 10) : int(1, 5);
  const dense = rand() < 0.5;
  const maxWeight = large ? (dense ? 1000 : int(10, 1000)) : int(1, 10);
  const extra = n === 1 ? 0 : large ? (dense ? int(500, 990) : int(0, 20)) : int(0, 4);
  // Shuffle the labels, then build a random spanning tree so every branch starts connected.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [label[i], label[j]] = [label[j], label[i]]; }
  const roads = [];
  for (let i = 1; i < n; i++) roads.push([label[i], label[int(0, i - 1)], int(1, maxWeight)]);
  for (let e = 0; e < extra; e++) {
    const u = int(0, n - 1);
    const v = (u + int(1, n - 1)) % n;
    roads.push([u, v, int(1, maxWeight)]);
  }
  for (let i = roads.length - 1; i > 0; i--) { const j = int(0, i); [roads[i], roads[j]] = [roads[j], roads[i]]; }
  const reach = large ? (dense ? int(1, 120) : int(1, 3 * maxWeight)) : int(1, 3 * maxWeight);
  return [n, Math.min(100000, reach), roads];
}
